/**
 * A simplified rendition of the Key Levels range bar from the Design mockups -- a horizontal track
 * spanning `axisLow`..`axisHigh`, a highlighted "value area" band, a fair-value tick, a support
 * tick, and a dot marking the current price. Not a pixel-match of the mockup (which also marks
 * resistance and has finer gradient detail); this keeps to the same Canvas-drawing technique
 * `PutCallHorizontalBar` already uses elsewhere (`drawRoundRect` + `drawLine` ticks) rather than a
 * new drawing approach, and conveys the same relationships: where the current price sits between
 * the value area and the wider low/high range.
 *
 * All positions are clamped into `[axisLow, axisHigh]` before being turned into a fraction -- a
 * value outside that range (e.g. price already broke through resistance) still renders at the
 * bar's edge instead of being silently dropped or drawn off-canvas.
 */
@Composable
fun PriceRangeBar(
    axisLow: Double,
    axisHigh: Double,
    valueAreaLow: Double,
    valueAreaHigh: Double,
    fairValueAnchor: Double,
    support: Double,
    currentPrice: Double,
    modifier: Modifier = Modifier
) {
    val pulseColors = LocalPulseColors.current
    val span = (axisHigh - axisLow).takeIf { it > 0 } ?: 1.0

    fun fractionOf(value: Double): Float =
        ((value.coerceIn(axisLow, axisHigh) - axisLow) / span).toFloat()

    val trackColor = pulseColors.surfaceTinted
    val valueAreaColor = pulseColors.accentSurface
    val fairValueColor = MaterialTheme.colorScheme.onSurface
    val supportColor = pulseColors.signalBullishText
    val priceColor = pulseColors.accentPrimary
    // 💡 `dimensionResource` is @Composable -- resolved here, in composition, rather than inside
    // Canvas's `onDraw: DrawScope.() -> Unit` lambda below, which runs at draw time and cannot
    // call composables. `.toPx()` on the resulting Dp is a plain DrawScope extension, so that part
    // is fine to call from inside the lambda.
    val tickWidthDp = dimensionResource(id = R.dimen.gauge_needle_width)

    Column(modifier = modifier.fillMaxWidth()) {
        Canvas(
            modifier = Modifier
                .fillMaxWidth()
                .height(dimensionResource(id = R.dimen.padding_xlarge))
        ) {
            val barHeight = size.height * 0.4f
            val barTop = (size.height - barHeight) / 2f

            drawRoundRect(
                color = trackColor,
                topLeft = Offset(0f, barTop),
                size = androidx.compose.ui.geometry.Size(size.width, barHeight),
                cornerRadius = CornerRadius(barHeight / 2, barHeight / 2)
            )

            val valueAreaStartX = fractionOf(valueAreaLow) * size.width
            val valueAreaEndX = fractionOf(valueAreaHigh) * size.width
            drawRoundRect(
                color = valueAreaColor,
                topLeft = Offset(valueAreaStartX, barTop),
                size = androidx.compose.ui.geometry.Size(valueAreaEndX - valueAreaStartX, barHeight),
                cornerRadius = CornerRadius(barHeight / 2, barHeight / 2)
            )

            fun tick(value: Double, color: Color) {
                val x = fractionOf(value) * size.width
                drawLine(
                    color = color,
                    start = Offset(x, 0f),
                    end = Offset(x, size.height),
                    strokeWidth = tickWidthDp.toPx(),
                    cap = StrokeCap.Round
                )
            }
            tick(fairValueAnchor, fairValueColor)
            tick(support, supportColor)

            val priceX = fractionOf(currentPrice) * size.width
            drawCircle(
                color = priceColor,
                radius = size.height / 2.2f,
                center = Offset(priceX, size.height / 2f)
            )
        }

        Row(modifier = Modifier.fillMaxWidth()) {
            Text(
                text = "$${axisLow.roundToInt()}",
                style = MaterialTheme.typography.labelSmall,
                color = pulseColors.onSurfaceMuted
            )
            androidx.compose.foundation.layout.Spacer(modifier = Modifier.weight(1f))
            Text(
                text = "$${axisHigh.roundToInt()}",
                style = MaterialTheme.typography.labelSmall,
                color = pulseColors.onSurfaceMuted
            )
        }
    }
}

